3	import java.util.regex.Pattern;
4	
5	/**
6	 * Converts a raw telephone into E.164 form. A leading {@code '+'} and country code are kept
7	 * when present; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
8	 * is dropped from the national digits. Spaces, dashes and brackets are stripped, and the result
9	 * must carry 8 to 15 digits after the {@code '+'}.
10	 *
11	 * <p>So {@code "0412 345 678"} becomes {@code "+61412345678"} and {@code "+64 21 123 456"}
12	 * becomes {@code "+6421123456"}.
13	 */
14	final class E164Telephone {
15	
16	    /** Country code assumed when the number carries no explicit {@code '+'} prefix. */
17	    private static final String DEFAULT_COUNTRY_CODE = "61";
18	
19	    /** Spaces, dashes and brackets, which carry no meaning in E.164. */
20	    private static final Pattern SEPARATORS = Pattern.compile("[\\s()\\-]");
21	
22	    /** A valid E.164 body: 8 to 15 digits following the {@code '+'}. */
23	    private static final Pattern E164_DIGITS = Pattern.compile("\\d{8,15}");
24	
25	    private E164Telephone() {
26	    }
27	
28	    /**
29	     * @param raw the telephone as supplied by the client.
30	     * @return the E.164 string (e.g. {@code "+61412345678"}), or {@code null} if {@code raw}
31	     *         cannot form a valid E.164 number.
32	     */
33	    static String format(String raw) {
34	        if (raw == null) {
35	            return null;
36	        }
37	        String cleaned = SEPARATORS.matcher(raw).replaceAll("");
38	        String digits;
39	        if (cleaned.startsWith("+")) {
40	            digits = cleaned.substring(1);
41	        }
42	        else {
43	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
44	            digits = DEFAULT_COUNTRY_CODE + national;
45	        }
46	        return E164_DIGITS.matcher(digits).matches() ? "+" + digits : null;
47	    }
48	}
