3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.Map;
6	import java.util.function.Function;
7	
8	import net.officefloor.plugin.variable.Out;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
11	import org.springframework.util.StringUtils;
12	import org.springframework.web.bind.annotation.RequestBody;
13	
14	/**
15	 * Rejects a create-owner request that is missing or blank in any required field, before
16	 * {@link BuildOwner} runs. Collects every offending field so the response reports them all
17	 * at once. Publishes the validated body for later steps, since the HTTP body is read once.
18	 * The address is checked in its normalized form (see {@link AddressNormalizer}), so an address
19	 * that is blank only once whitespace is collapsed is rejected too.
20	 */
21	public class ValidateRequiredOwnerFields {
22	
23	    /** Required fields, paired with their accessor, in the order reported. */
24	    private static final List<Map.Entry<String, Function<OwnerFieldsDto, String>>> REQUIRED = List.of(
25	            Map.entry("firstName", OwnerFieldsDto::getFirstName),
26	            Map.entry("lastName", OwnerFieldsDto::getLastName),
27	            Map.entry("address", dto -> AddressNormalizer.normalize(dto.getAddress())),
28	            Map.entry("city", OwnerFieldsDto::getCity),
29	            Map.entry("telephone", OwnerFieldsDto::getTelephone));
30	
31	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
32	            throws MissingOwnerFieldsException {
33	        List<String> missing = new ArrayList<>();
34	        for (Map.Entry<String, Function<OwnerFieldsDto, String>> field : REQUIRED) {
35	            if (!StringUtils.hasText(field.getValue().apply(request))) {
36	                missing.add(field.getKey());
37	            }
38	        }
39	        if (!missing.isEmpty()) {
40	            throw new MissingOwnerFieldsException(missing);
41	        }
42	        validated.set(request);
43	    }
44	}
